import 'svelte/internal/disclose-version';
import * as $ from 'svelte/internal/client';
import { onMount } from "svelte";
import { page } from "$app/stores";
import { goto } from "$app/navigation";
import { fetchProfileMetadata } from "$lib/utils/nostr-message";
import { getNpub } from "$lib/utils/nostrKeys";
import { nip19 } from "nostr-tools";
import ChatView from "$lib/components/messages/ChatView.svelte";
import Avatar from "$lib/components/Avatar.svelte";

function goBackToMessages() {
	goto("/dashboard/messages");
}

var root_1 = $.template(`<div class="flex h-full items-center justify-center"><div class="loading loading-spinner loading-lg"></div></div>`);
var root_3 = $.template(`<div class="flex h-full flex-col items-center justify-center"><div class="alert alert-error alert-outline max-w-md"><svg xmlns="http://www.w3.org/2000/svg" class="h-6 w-6 shrink-0 stroke-current" fill="none" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z"></path></svg> <span> </span></div> <button class="btn btn-primary mt-4">Back to Messages</button></div>`);

var on_click = (_, recipientPubkey) => {
	navigator.clipboard.writeText($.get(recipientPubkey)); // Optional: Add a toast notification here
};

var root_4 = $.template(`<div class="border-base-300 flex flex-shrink-0 items-center gap-3 border-b p-4"><button class="btn btn-ghost btn-sm" aria-label="Go back to messages"><svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"></path></svg></button> <div class="flex flex-1 items-center justify-between"><div class="flex items-center gap-3"><!> <div><h3 class="text-lg font-semibold"> </h3></div></div> <button class="btn btn-ghost btn-sm" title="Copy public key" aria-label="Copy public key"><svg xmlns="http://www.w3.org/2000/svg" class="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3"></path></svg></button></div></div> <div class="min-h-0 flex-1 overflow-hidden"><!></div>`, 1);
var root = $.template(`<div class="bg-base-100 flex h-full max-h-screen flex-col rounded-[2rem]"><!></div>`);

export default function _page($$anchor, $$props) {
	$.push($$props, true);

	const [$$stores, $$cleanup] = $.setup_stores();
	const $page = () => $.store_get(page, '$page', $$stores);
	let recipientPubkey = $.derived(() => $page().params.pubkey);
	let currentUserNpub = $.state("");
	let recipientProfile = $.state(null);
	let isLoading = $.state(true);
	let error = $.state("");

	onMount(async () => {
		try {
			$.set(currentUserNpub, await getNpub(), true);

			let hexPubkey = $.get(recipientPubkey);

			if ($.get(recipientPubkey).startsWith("npub")) {
				try {
					hexPubkey = nip19.decode($.get(recipientPubkey)).data;
				} catch {
					$.set(error, "Invalid npub format");
					$.set(isLoading, false);
					return;
				}
			} else if (!(/^[a-fA-F0-9]{64}$/).test($.get(recipientPubkey))) {
				$.set(error, "Invalid public key format");
				$.set(isLoading, false);
				return;
			}

			if (hexPubkey !== $.get(recipientPubkey)) {
				goto(`/dashboard/messages/to/${hexPubkey}`, { replaceState: true });
				return;
			}

			try {
				const profile = await fetchProfileMetadata(hexPubkey);

				$.set(recipientProfile, profile, true);
			} catch(profileErr) {
				console.error("Failed to fetch recipient profile:", profileErr);
			}
		} catch(err) {
			$.set(error, err instanceof Error ? err.message : "Failed to load chat", true);
		} finally {
			$.set(isLoading, false);
		}
	});

	var div = root();
	var node = $.child(div);

	{
		var consequent = ($$anchor) => {
			var div_1 = root_1();

			$.append($$anchor, div_1);
		};

		var alternate = ($$anchor, $$elseif) => {
			{
				var consequent_1 = ($$anchor) => {
					var div_2 = root_3();
					var div_3 = $.child(div_2);
					var span = $.sibling($.child(div_3), 2);
					var text = $.child(span, true);

					$.reset(span);
					$.reset(div_3);

					var button = $.sibling(div_3, 2);

					button.__click = [goBackToMessages];
					$.reset(div_2);
					$.template_effect(() => $.set_text(text, $.get(error)));
					$.append($$anchor, div_2);
				};

				var alternate_1 = ($$anchor) => {
					var fragment = root_4();
					var div_4 = $.first_child(fragment);
					var button_1 = $.child(div_4);

					button_1.__click = [goBackToMessages];

					var div_5 = $.sibling(button_1, 2);
					var div_6 = $.child(div_5);
					var node_1 = $.child(div_6);

					const expression = $.derived(() => ({
						name: $.get(recipientProfile)?.name || 'Unknown',
						picture: $.get(recipientProfile)?.picture || null
					}));

					Avatar(node_1, {
						get user() {
							return $.get(expression);
						},
						size: 'sm'
					});

					var div_7 = $.sibling(node_1, 2);
					var h3 = $.child(div_7);
					var text_1 = $.child(h3, true);

					$.reset(h3);
					$.reset(div_7);
					$.reset(div_6);

					var button_2 = $.sibling(div_6, 2);

					button_2.__click = [on_click, recipientPubkey];
					$.reset(div_5);
					$.reset(div_4);

					var div_8 = $.sibling(div_4, 2);
					var node_2 = $.child(div_8);

					ChatView(node_2, {
						get recipientPubkey() {
							return $.get(recipientPubkey);
						},
						get currentUserPubkey() {
							return $.get(currentUserNpub);
						},
						get initialProfile() {
							return $.get(recipientProfile);
						}
					});

					$.reset(div_8);

					$.template_effect(($0) => $.set_text(text_1, $0), [
						() => $.get(recipientProfile)?.name || `${$.get(recipientPubkey).slice(0, 8)}...`
					]);

					$.append($$anchor, fragment);
				};

				$.if(
					$$anchor,
					($$render) => {
						if ($.get(error)) $$render(consequent_1); else $$render(alternate_1, false);
					},
					$$elseif
				);
			}
		};

		$.if(node, ($$render) => {
			if ($.get(isLoading)) $$render(consequent); else $$render(alternate, false);
		});
	}

	$.reset(div);
	$.append($$anchor, div);
	$.pop();
	$$cleanup();
}

$.delegate(['click']);
